# -*- coding: utf-8 -*-
from pathlib import Path
import pandas as pd,numpy as np,json
p=Path(__file__).parent/'progress_r3_first100m';a=pd.read_csv(p/'fixed_frames.csv');b=pd.read_csv(Path(__file__).parent/'progress_20261017_1535/fixed_frames.csv');b=b[b.name.str.contains('relax_n200_')];d=pd.concat([a,b]).drop_duplicates(['name','step','h']);d=d[d.step.between(50000000,100000000)&d.step.mod(10000000).eq(0)].copy();d['F']=d.name.str.extract(r'_F([\d.]+)').astype(float);d['seed']=d.name.str.extract(r'_r(\d+)').astype(int);assert (d.Nplus-d.Nminus==4).all() and d.composite.eq(0).all();s=d.groupby(['F','h','seed'])[['Nminus','P4','pair_density']].mean().reset_index();s.to_csv(p/'seed_window.csv',index=False);g=s.groupby(['F','h']).agg(Nminus=('Nminus','mean'),SD=('Nminus','std'),P4=('P4','mean'),rho=('pair_density','mean'),seeds=('seed','count'));g.to_csv(p/'three_seed_summary.csv');print(g);(p/'validation.json').write_text(json.dumps(dict(frames=len(d),window=[50000000,100000000],stride=10000000,topology=True,seeds_per_condition=3),indent=2))
(p/'report_zh.md').write_text('# n200 首亿步三种子阶段分析\n\n固定L5球面网格、h=1.5/3，匹配5000万至1亿步每1000万步的完整帧。先对每种子取时间平均，再报告三个种子的均值及样本SD。\n\n'+g.to_string()+'\n\n第三种子在CPU2用4 MPI，另两种子在CPU5用2 MPI；自定义bd/sphere的噪声按MPI rank播种，因此相同输入种子不会逐步复现2 MPI轨迹。三个种子共享同尺寸初始几何。这个阶段只能说明有限时间统计，不是稳态或独立初态不确定度。\n',encoding='utf-8')
